<template>
 <div v-loading="loading">
  <el-alert :title="mode==='orders'?'发货预通知不等于收货；采购方确认到货后进入质检。支持分批交付，累计发货不能超过可交付数量。':'发票须关联已确认对账单。金额为含税金额，上传后待采购方验真；本系统不提供税务机关验真服务。'" type="info" :closable="false"/>
  <el-tabs v-if="mode==='orders'" v-model="tab" @tab-click="reset"><el-tab-pane label="我的采购订单" name="orders"/><el-tab-pane label="交付记录" name="deliveries"/></el-tabs>
  <ListFilters :key="resource" :only-resources="[resource]" :provided-schemas="schemas" @query="reset"/>
  <el-button v-if="mode==='invoices'" type="primary" @click="openInvoice">上传发票</el-button>
  <el-table :key="'table-'+resource" :data="items" border style="margin-top:16px">
   <template v-if="mode==='orders'&&tab==='orders'"><el-table-column prop="order_no" label="订单编号" min-width="145"/><el-table-column prop="factory_code" label="收货工厂"/><el-table-column prop="delivery_address" label="收货地址"/><el-table-column prop="total_amount" label="订单含税金额"/><el-table-column prop="currency" label="币种"/><el-table-column label="物料明细" min-width="190"><template slot-scope="s"><div v-for="(l,i) in s.row.lines" :key="i">{{l.material_code}} · {{l.material_name}} × {{l.quantity}}{{l.unit}}</div></template></el-table-column></template>
   <template v-else-if="mode==='orders'"><el-table-column prop="order_no" label="订单号"/><el-table-column prop="material_code" label="物料编码"/><el-table-column prop="quantity" label="本次发货数"/><el-table-column prop="carrier" label="承运商"/><el-table-column prop="tracking_no" label="运单号"/><el-table-column prop="shipped_date" label="发货日期"/><el-table-column prop="expected_date" label="预计到货"/></template>
   <template v-else><el-table-column prop="invoice_no" label="发票号码"/><el-table-column prop="order_no" label="订单号"/><el-table-column prop="amount" label="含税金额"/><el-table-column prop="tax_amount" label="税额"/><el-table-column prop="invoice_date" label="开票日期"/><el-table-column prop="file_name" label="发票文件"/></template>
   <el-table-column label="状态"><template slot-scope="s"><el-tag>{{statusName(s.row.status)}}</el-tag></template></el-table-column>
   <el-table-column label="操作" width="175"><template slot-scope="s"><template v-if="mode==='orders'&&tab==='orders'"><el-button v-if="s.row.status==='sent'" type="text" @click="confirm(s.row)">确认接单</el-button><el-button v-if="['supplier_confirmed','partially_delivered','quality_tracking'].includes(s.row.status)" type="text" @click="openDelivery(s.row)">登记发货</el-button></template><template v-else-if="mode==='orders'"><el-button v-if="s.row.status==='in_transit'" type="text" @click="withdraw(s.row)">撤回发货</el-button></template><template v-else><el-button v-if="s.row.file_name" type="text" @click="download(s.row)">下载发票</el-button><el-button v-if="s.row.file_name&&['received','rejected'].includes(s.row.status)" type="text" @click="withdraw(s.row)">撤回重传</el-button></template></template></el-table-column>
  </el-table><Pager :page="pagination" @change="p=>{pagination.page=p;load()}" @size="s=>{pagination.page_size=s;reset()}"/>
  <el-dialog :title="mode==='orders'?'登记订单交付':'上传供应商发票'" :visible.sync="visible" width="620px" append-to-body :close-on-click-modal="false">
   <el-form label-width="115px">
    <template v-if="mode==='orders'"><el-form-item label="采购订单">{{selected.order_no}}</el-form-item><el-form-item label="发货物料"><el-select v-model="form.material_code" style="width:100%"><el-option v-for="l in selected.lines||[]" :key="l.material_code" :value="l.material_code" :label="l.material_code+' · '+l.material_name"/></el-select></el-form-item><el-form-item label="本次发货数量"><el-input-number v-model="form.quantity" :min="0.0001" :precision="4"/></el-form-item><el-form-item label="承运商"><el-input v-model.trim="form.carrier" maxlength="120"/></el-form-item><el-form-item label="运单号"><el-input v-model.trim="form.tracking_no" maxlength="120"/></el-form-item><el-form-item label="发货日期"><el-date-picker v-model="form.shipped_date" value-format="yyyy-MM-dd"/></el-form-item><el-form-item label="预计到货日期"><el-date-picker v-model="form.expected_date" value-format="yyyy-MM-dd"/></el-form-item></template>
    <template v-else><el-form-item label="已确认对账单"><el-select v-model="form.reconciliation_id" filterable style="width:100%"><el-option v-for="r in reconciliations" :key="r.id" :value="r.id" :label="r.order_no+' / '+r.reconciliation_no+' / 可开票 '+r.remaining" :disabled="Number(r.remaining)<=0"/></el-select><p v-if="!reconciliations.length">尚无已确认对账单，请联系采购方完成对账。</p></el-form-item><el-form-item label="发票号码"><el-input v-model.trim="form.invoice_no" maxlength="64"/></el-form-item><el-form-item label="含税金额"><el-input-number v-model="form.amount" :min="0.01" :precision="2"/></el-form-item><el-form-item label="税额"><el-input-number v-model="form.tax_amount" :min="0" :precision="2"/></el-form-item><el-form-item label="开票日期"><el-date-picker v-model="form.invoice_date" value-format="yyyy-MM-dd"/></el-form-item><el-form-item label="发票文件"><input ref="invoiceFile" type="file" accept=".pdf,.png,.jpg,.jpeg" @change="file=$event.target.files[0]"/><p>支持 PDF / PNG / JPEG，最大 10MB。</p></el-form-item></template>
   </el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">提交</el-button></span>
  </el-dialog>
 </div>
</template>
<script>
import axios from 'axios';
import Pager from './Pager.vue';
import ListFilters from './ListFilters.vue';
import {listQueryFilters} from '../api/client';
const client=axios.create({baseURL:process.env.VUE_APP_API_BASE_URL||'/api/v1',timeout:30000});
const field=(name,label,type='text')=>({name,label,type});
export default {components:{Pager,ListFilters},props:{token:String,mode:String},data:()=>({tab:'orders',items:[],loading:false,saving:false,visible:false,selected:{},form:{},file:null,reconciliations:[],pagination:{page:1,page_size:10,total:0},schemas:[{resource:'supplier/orders',label:'我的采购订单',fields:[field('order_no','订单号'),field('material_code','物料编码'),field('status','状态'),field('created_at','创建时间','datetime')]},{resource:'supplier/deliveries',label:'交付记录',fields:[field('carrier','承运商'),field('tracking_no','运单号'),field('shipped_date','发货日期','date'),field('expected_date','预计到货日期','date')]},{resource:'supplier/invoices',label:'我的发票',fields:[field('invoice_no','发票号码'),field('amount','含税金额','number'),field('invoice_date','开票日期','date'),field('status','状态')]}]}),computed:{resource(){return 'supplier/'+(this.mode==='invoices'?'invoices':this.tab);}},created(){this.load();},methods:{headers(){return {Authorization:'Bearer '+this.token};},error(e){const d=e.response?.data?.detail;this.$message.error(typeof d==='string'?d:d?.[0]?.msg||'操作失败');if(e.response?.status===401)this.$emit('expired');},statusName(s){return {sent:'待接单',supplier_confirmed:'待送货',partially_delivered:'部分交付',quality_tracking:'质量追溯',completed:'完成',in_transit:'运输中/待收货',received:this.mode==='invoices'?'待验真':'已收货待质检',inspected:'已质检',verified:'已验真',rejected:'已驳回'}[s]||s;},reset(){this.pagination.page=1;this.load();},async load(){this.loading=true;try{const r=(await client.get('/'+this.resource,{params:{...this.pagination,filters:JSON.stringify(listQueryFilters[this.resource]||[])},headers:this.headers()})).data;this.items=r.items;this.pagination.total=r.total;}catch(e){this.error(e);}finally{this.loading=false;}},async confirm(row){try{await this.$confirm('确认接受该采购订单？','确认接单');await client.post('/supplier/orders/'+row.id+'/confirm',{}, {headers:this.headers()});await this.load();this.$message.success('接单成功，可以登记发货');}catch(e){if(e!=='cancel')this.error(e);}},openDelivery(row){this.selected=row;this.form={order_id:row.id,material_code:row.lines[0]?.material_code||'',quantity:1,carrier:'',tracking_no:'',shipped_date:'',expected_date:''};this.visible=true;},async openInvoice(){try{this.reconciliations=[];let page=1,total=1;while(this.reconciliations.length<total){const r=(await client.get('/supplier/reconciliations',{params:{page,page_size:100},headers:this.headers()})).data;this.reconciliations.push(...r.items);total=r.total;page++;}this.form={reconciliation_id:'',invoice_no:'',amount:0.01,tax_amount:0,invoice_date:''};this.file=null;this.visible=true;this.$nextTick(()=>{if(this.$refs.invoiceFile)this.$refs.invoiceFile.value='';});}catch(e){this.error(e);}},async save(){if(this.mode==='invoices'&&(!this.file||!this.form.reconciliation_id||!this.form.invoice_no||!this.form.invoice_date))return this.$message.warning('请填写发票信息并选择文件');if(this.mode==='orders'&&(!this.form.carrier||!this.form.tracking_no||!this.form.shipped_date||!this.form.expected_date))return this.$message.warning('请填写发货日期和物流信息');this.saving=true;try{let payload=this.form;if(this.mode==='invoices'){payload=new FormData();Object.entries(this.form).forEach(([k,v])=>payload.append(k,v));payload.append('file',this.file);}await client.post('/supplier/'+(this.mode==='invoices'?'invoices':'deliveries'),payload,{headers:this.headers()});this.visible=false;if(this.mode==='orders')this.tab='deliveries';this.reset();this.$message.success(this.mode==='orders'?'发货预通知已发送，等待采购方收货':'发票已上传，等待采购方审核');}catch(e){this.error(e);}finally{this.saving=false;}},async withdraw(row){try{await this.$confirm('确认撤回？如需修改，可重新提交。','撤回记录');await client.delete('/'+this.resource+'/'+row.id,{headers:this.headers()});this.reset();}catch(e){if(e!=='cancel')this.error(e);}},async download(row){try{const r=await client.get('/supplier/invoices/'+row.id+'/file',{headers:this.headers(),responseType:'blob'});const u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;a.download=row.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){this.error(e);}}}};
</script>
